import socket
# raw DNS query to 127.0.0.11 for prices.internal
import struct
def q(name, server='127.0.0.11'):
    tid=1234
    hdr=struct.pack('>HHHHHH', tid, 0x0100,1,0,0,0)
    for part in name.split('.'): hdr += bytes([len(part)])+part.encode()
    hdr += b'\0'+struct.pack('>HH',1,1)
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
    s.sendto(hdr,(server,53))
    try:
        data,_=s.recvfrom(512)
        print(name, data[-8:].hex(), 'ancount', struct.unpack('>H',data[6:8])[0], data[12:].hex())
